+func (c *Client) Start(ctx context.Context, exe string, args []string) (*jobpb.StartResponse, error) {
+	return c.svc.Start(ctx, &jobpb.StartRequest{
+		Spec: &jobpb.JobSpec{
+			Exe:  exe,
+			Args: args,
+		},
+	})
+}
